    solution: "\u6211\u4EEC\u5750\u5728\u7535\u5F71\u9662\u91CC\uFF0C\u770B\u7684\u662F\u94F6\u5E55\u4E0A\u7684\u7535\u5F71\u3002\u773C\u719F\u7684\u4EBA\u662F\u7ECF\u5E38\u5728\u5F71\u89C6\u4F5C\u54C1\u4E2D\u51FA\u73B0\u7684\u6F14\u5458\uFF0C\u4E0D\u662F\u6211\u7684\u719F\u4EBA\uFF1B\u67AA\u58F0\u548C\u5012\u4E0B\u7684\u4EBA\u5C5E\u4E8E\u5267\u60C5\u3002\u7535\u5F71\u7ED3\u675F\uFF0C\u653E\u6620\u5385\u706F\u4EAE\uFF0C\u89C2\u4F17\u624D\u79BB\u573A\u3002\u73B0\u573A\u6CA1\u6709\u771F\u7684\u53D1\u751F\u4F24\u4EBA\u4E8B\u4EF6\u3002",
