        text: "\u4E24\u5EA7\u5C9B\u5728\u5B66\u751F\u7B14\u8BB0\u672C\u7684\u5DE6\u53F3\u4E24\u9875\uFF0C\u6DF1\u6C9F\u662F\u88C5\u8BA2\u7F1D\uFF0C\u6545\u4E8B\u53D1\u751F\u5728\u753B\u4E2D\u5E7B\u60F3\u4E16\u754C\u3002",
        required: true
