function guessKey(value){
  return value.normalize("NFKC").toLowerCase().trim().replace(/^(?:我猜是|我觉得是|答案是|应该是)/,"").replace(/[\s\p{P}]/gu,"");
}
function matchesGuess(card,guess){
  const text=guessKey(guess);
  if(!text)return false;
  const candidates=[card.options[card.correct],card.solution,card.solution.split(/[。！？]/)[0],...(commonGuesses[card.id]||[])];
  return candidates.some(c=>guessKey(c)===text);
}
async function scoreChallenge(me,p){
  const card=challengeBank.find(c=>c.id===p.question);
  if(!card)return answer({error:"题目不存在"},400);
  const written=p.format==="written", reveal=written&&p.reveal===true;
  let choice=p.choice;
  if(written){
    const guess=typeof p.guess==="string"?p.guess.trim():"";
    if(!reveal&&(!guess||guess.length>240))return answer({error:"请写下你的回答（最多240字）"},400);
    choice=reveal?-2:matchesGuess(card,guess)?card.correct:-1;
  }else if(!Number.isInteger(choice)||choice<0||choice>=card.options.length)return answer({error:"请选择有效答案"},400);
  const verdict=(pick,practice)=>answer({choice:pick,correct:card.correct,solution:card.solution,practice,...(written?{answer:card.options[card.correct],matched:pick===card.correct,revealed:pick===-2}:{})});
  const store = db();
  if (p.practice === true) {
    const existing = await store.prepare("SELECT 1 FROM riddle_attempts WHERE member=? AND question=?").bind(me, card.id).first();
    if (!existing) return answer({ error: "\u8BF7\u5148\u5B8C\u6210\u672C\u9898" }, 409);
    return verdict(choice,true);
  }
  const [, saved] = await store.batch([
    store.prepare("INSERT OR IGNORE INTO riddle_attempts(member,question,choice,right_answer) VALUES(?,?,?,?)").bind(me, card.id, choice, Number(choice === card.correct)),
    store.prepare("SELECT choice FROM riddle_attempts WHERE member=? AND question=?").bind(me, card.id)
  ]);
  return verdict(saved.results[0].choice,false);
}
async function readRanks() {
  const [result] = await db().batch([db().prepare(`SELECT CAST(a.slot AS TEXT) AS member,COALESCE(p.name,a.username) AS name,
  COUNT(t.question) AS attempted,COALESCE(SUM(t.right_answer),0) AS right FROM camp_accounts a
  LEFT JOIN camp_profiles p ON p.id=CAST(a.slot AS TEXT)
  LEFT JOIN riddle_attempts t ON t.member=CAST(a.slot AS TEXT) GROUP BY a.slot ORDER BY right DESC,a.slot`)]);
  let place = 0, last = -1;
  return answer({ total: challengeBank.length, rows: result.results.map((entry, i) => {
    const r = entry;
    if (r.right !== last) {
      place = i + 1;
      last = r.right;
    }
    return { ...r, place };
  }) });
}

