var pageSize = 12;
async function readRiddles(params) {
  const store = db(), id = params.get("reveal");
  if (id !== null) {
    if (!/^[1-9]\d*$/.test(id) || !Number.isSafeInteger(Number(id))) return answer({ error: "\u9898\u53F7\u65E0\u6548" }, 400);
    const r = await store.prepare("SELECT solution FROM team_riddles WHERE id=?").bind(Number(id)).first();
    return r ? answer(r) : answer({ error: "\u6CA1\u6709\u627E\u5230\u8FD9\u9053\u9898" }, 404);
  }
  const before = Number(params.get("before") ?? Number.MAX_SAFE_INTEGER);
  if (!Number.isSafeInteger(before) || before < 1) return answer({ error: "\u9875\u7801\u65E0\u6548" }, 400);
  const [page] = await store.batch([store.prepare("SELECT id,author,prompt FROM team_riddles WHERE id<? ORDER BY id DESC LIMIT ?").bind(before, pageSize + 1)]);
  return answer({ items: page.results.slice(0, pageSize), more: page.results.length > pageSize });
}
async function publishRiddle(author, p) {
  const prompt = typeof p.prompt === "string" ? p.prompt.trim() : "", solution = typeof p.solution === "string" ? p.solution.trim() : "";
  if (!prompt || !solution || prompt.length > 160 || solution.length > 240) return answer({ error: "\u8BF7\u586B\u5199\u9898\u9762\uFF08\u6700\u591A 160 \u5B57\uFF09\u548C\u8C1C\u5E95\uFF08\u6700\u591A 240 \u5B57\uFF09" }, 400);
  if (typeof p.key !== "string" || !/^[a-f0-9-]{36}$/i.test(p.key)) return answer({ error: "\u53D1\u5E03\u7F16\u53F7\u65E0\u6548" }, 400);
  const store = db();
  const [, saved] = await store.batch([
    store.prepare("INSERT INTO team_riddles(author,request_key,prompt,solution) VALUES(?,?,?,?) ON CONFLICT(author,request_key) DO NOTHING").bind(author, p.key, prompt, solution),
    store.prepare("SELECT id,prompt,solution FROM team_riddles WHERE author=? AND request_key=?").bind(author, p.key)
  ]);
  const row = saved.results[0];
  return row.prompt === prompt && row.solution === solution ? answer({ id: row.id }) : answer({ error: "\u4E0A\u6B21\u53D1\u5E03\u5DF2\u6210\u529F\uFF0C\u8BF7\u91CD\u65B0\u51FA\u9898" }, 409);
}

