    const from = p.from, to = p.to;
    if (typeof from !== "number" || typeof to !== "number" || ![0, 1, 2].includes(from) || ![0, 1, 2].includes(to) || Math.abs(to - from) !== 1) return answer2("\u4E0A\u4E0B\u73ED\u72B6\u6001\u65E0\u6548", 400);
